using System.Linq;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Mvc.Filters;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.DependencyInjection;

public class ProblemExceptionFilter : IExceptionFilter
{
    public void OnException(ExceptionContext context)
    {
        if (context.Exception is not ProblemException problem) return;
        var details = new ProblemDetails { Status = problem.Status, Title = problem.Message };
        context.HttpContext.Response.Headers.Remove("ETag");
        if (problem.ETag is not null) context.HttpContext.Response.Headers.ETag = $"\"{problem.ETag}\"";
        context.Result = new ObjectResult(details) { StatusCode = problem.Status, ContentTypes = { "application/problem+json" } };
        context.ExceptionHandled = true;
    }
}

// [Required] documents If-Match as a required header; the service answers 428 itself after the 400 checks, so drop the binding error here.
public class IfMatchPrecedenceFilter : IActionFilter, IOrderedFilter
{
    public int Order => int.MinValue;

    public void OnActionExecuting(ActionExecutingContext context) => context.ModelState.Remove("If-Match");

    public void OnActionExecuted(ActionExecutedContext context) { }
}

public static class AppSetup
{
    public static void ConfigureServices(IServiceCollection services, string sqliteConnectionString)
    {
        services.AddDbContext<BlogContext>(options => options.UseSqlite(sqliteConnectionString));
        services.AddScoped<BlogService>();
        services.AddScoped<PostService>();
        services.Configure<MvcOptions>(options => { options.Filters.Add<ProblemExceptionFilter>(); options.Filters.Add(new IfMatchPrecedenceFilter()); });
    }
}
