        var hash = Representation.Hash(body);
        var blog = new Blog { PublicId = body.Id, Name = body.Name, ETag = hash, CreationHash = hash };
        database.Blogs.Add(blog);
        try
        {
            await database.SaveChangesAsync(cancellationToken);
